 CREATE Proc [dbo].[ReportVendorWisePurchaseReport] @From as datetime,@To as Datetime,@Login as nvarchar(max),@VendorId as text as Declare @ReportName as nvarchar(max); set @ReportName='Goods Purchasing Vendor wise'; select CONVERT(VARCHAR(11),@From,106) as [From],CONVERT(VARCHAR(11),@To,106) as [To],im.RefrenceNo as LoginUser,im.Date,gm.GRNo,v.Vendor,@ReportName as store,c.Category,sc.Subcategory,i.Item, idc.TotalPackage,idc.PcsPerPackage as UnitQty, (Select Unit from unit  where UId=idc.PackageId) as PackingType, im.InvoiceNo,  im.Discount,ps.PONo, Un.Unit as IssuanceType,iu.IssFactor,iu.PurFactor, Uni.Unit as ReceipeType,iu.RecpFactor,UT.Unit as PurchaseUnit,iu.PkFactor, (Select Distinct(Unit) from unit  where UId=idc.Unit) as UnitType, (select ParLevel from ItemParLevel where ItemId= i.ItemId and SId = s.SId) as ParLevel, idc.Rate as UnitPrice, idc.Qty as PurchaseQty from InvoiceMaster_CompanyNew im inner join InvoiceDetail_CompanyNew idc on im.InvoiceId=idc.InvoiceId inner join GRNMaster gm on gm.GRNId=idc.GRNId left join PurchaseOrderMaster_Store ps on ps.POId=idc.POId inner join Vendor v on v.VId=im.VId inner join Store s on im.SId=s.SId inner join Item i on idc.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join Unit Un on iu.IssUnit=Un.UId inner join Unit Uni on iu.RecpUnit=Uni.UId inner join Unit UT on iu.PurUnit=UT.UId inner join Split(@VendorId,',') sp on sp.items = v.VId where im.Date between @From and @To  group by im.Date, im.InvoiceNo,gm.GRNo,v.Vendor,c.Category,sc.Subcategory,i.Item,idc.TotalPackage, idc.PcsPerPackage,idc.PackageId,U.Unit, im.Discount,ps.PONo,Un.Unit,iu.IssFactor,iu.PurFactor,Uni.Unit, iu.RecpFactor,UT.Unit,iu.PkFactor, idc.Unit, idc.Rate,idc.Qty,s.SId,i.ItemId,im.RefrenceNo order by im.date asc
